using ApplicationLayer;
using CoreModels;
using DataAccessLayer;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace AzureGuard.Controllers; [ApiController][Authorize][Route("api/projects")] public class ProjectsController(AppDbContext db, RepositoryAnalyzer analyzer) : ControllerBase { [HttpGet] public async Task<IActionResult> List() => Ok(await db.Projects.Where(x => x.IsActive).OrderByDescending(x => x.CreatedAt).ToListAsync()); [HttpGet("{id:long}")] public async Task<IActionResult> Get(long id) { var x = await db.Projects.FindAsync(id); return x is null ? NotFound() : Ok(x); } [HttpPost] public async Task<IActionResult> Create(CreateProjectRequest r, CancellationToken cancellationToken) { if (string.IsNullOrWhiteSpace(r.Name) || !Uri.TryCreate(r.RepositoryUrl, UriKind.Absolute, out var uri) || uri.Host != "github.com") return BadRequest("A name and public GitHub repository URL are required."); var branch = string.IsNullOrWhiteSpace(r.BranchName) ? "main" : r.BranchName.Trim(); var analysis = await analyzer.AnalyzeAsync(r.RepositoryUrl, branch, cancellationToken); var x = new Project { Name = r.Name.Trim(), Description = r.Description, RepositoryUrl = r.RepositoryUrl.Trim(), BranchName = branch, TechStack = analysis.TechStack, BuildCommand = analysis.BuildCommand, TestCommand = analysis.TestCommand, DockerfilePath = analysis.DockerfilePath, HelmChartPath = analysis.HelmChartPath, CreatedByUserId = User.GetUserId() }; db.Projects.Add(x); await db.SaveChangesAsync(); db.AuditLogs.Add(new AuditLog { UserId = User.GetUserId(), ProjectId = x.Id, Action = "PROJECT_CREATED" }); await db.SaveChangesAsync(); return CreatedAtAction(nameof(Get), new { id = x.Id }, x); } [HttpPut("{id:long}")] public async Task<IActionResult> Update(long id, CreateProjectRequest r, CancellationToken cancellationToken) { var x = await db.Projects.FindAsync(id); if (x is null) return NotFound(); x.Name = r.Name.Trim(); x.Description = r.Description; x.RepositoryUrl = r.RepositoryUrl.Trim(); x.BranchName = string.IsNullOrWhiteSpace(r.BranchName) ? x.BranchName : r.BranchName.Trim(); var analysis = await analyzer.AnalyzeAsync(x.RepositoryUrl, x.BranchName, cancellationToken); x.TechStack = analysis.TechStack; x.BuildCommand = analysis.BuildCommand; x.TestCommand = analysis.TestCommand; x.DockerfilePath = analysis.DockerfilePath; x.HelmChartPath = analysis.HelmChartPath; await db.SaveChangesAsync(); return Ok(x); } [HttpDelete("{id:long}")] public async Task<IActionResult> Delete(long id) { var x = await db.FindAsync<Project>(id); if (x is null) return NotFound(); x.IsActive = false; await db.SaveChangesAsync(); return NoContent(); } }
public static class ClaimsExtensions { public static long? GetUserId(this System.Security.Claims.ClaimsPrincipal user) => long.TryParse(user.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value, out var id) ? id : null; }
